19	namespace pto {
20	template <typename TileData>
21	AICORE constexpr typename TileData::DType getPadValue()
22	{
23	    switch (TileData::PadVal) {
24	        case PadValue::Null:
25	        case PadValue::Zero: {
26	            if constexpr (std::is_same_v<typename TileData::DType, int4b_t>) {
27	                return int4b_t(0);
28	            } else {
29	                return typename TileData::DType(0);
30	            }
31	        }
32	        case PadValue::Min:
33	            if constexpr (std::numeric_limits<typename TileData::DType>::has_infinity) {
34	                return -std::numeric_limits<typename TileData::DType>::infinity();
35	            } else {
36	                return std::numeric_limits<typename TileData::DType>::min();
37	            }
38	        case PadValue::Max:
39	            if constexpr (std::numeric_limits<typename TileData::DType>::has_infinity) {
40	                return std::numeric_limits<typename TileData::DType>::infinity();
41	            } else {
42	                return std::numeric_limits<typename TileData::DType>::max();
43	            }
44	    }
45	    if constexpr (std::is_same_v<typename TileData::DType, int4b_t>) {
46	        return int4b_t(0);
47	    } else {
48	        return 0;
49	    }
50	}
51	
52	template <typename TileData, typename GlobalData>
53	PTO_INLINE void CheckTileData(TileData& dst, GlobalData& src)
54	{
55	    static_assert(
56	        sizeof(typename TileData::DType) == sizeof(typename GlobalData::DType),
57	        "Source dtype must be same with dst dtype");
58	    static_assert(
59	        GlobalData::layout == pto::Layout::ND || GlobalData::layout == pto::Layout::DN ||
60	            GlobalData::layout == pto::Layout::NZ || GlobalData::layout == pto::Layout::MX_A_ND ||
61	            GlobalData::layout == pto::Layout::MX_A_DN || GlobalData::layout == pto::Layout::MX_A_ZZ ||
62	            GlobalData::layout == pto::Layout::MX_B_ND || GlobalData::layout == pto::Layout::MX_B_DN ||
63	            GlobalData::layout == pto::Layout::MX_B_NN,
64	        "Only ND, DN, NZ and MX_* GLobal Tensors are currently supported");
65	
66	    if constexpr (GlobalData::layout == pto::Layout::NZ) {
67	        assert(
68	            dst.GetValidRow() == src.GetShape(GlobalTensorDim::DIM_2) * src.GetShape(GlobalTensorDim::DIM_3) &&
69	            dst.GetValidCol() == src.GetShape(GlobalTensorDim::DIM_0) * src.GetShape(GlobalTensorDim::DIM_1) *
70	                                     src.GetShape(GlobalTensorDim::DIM_4));
71	    } else if constexpr (GlobalData::layout == pto::Layout::ND || GlobalData::layout == pto::Layout::DN) {
72	        assert(
73	            (src.GetShape(GlobalTensorDim::DIM_0) * src.GetShape(GlobalTensorDim::DIM_1) *
74	                     src.GetShape(GlobalTensorDim::DIM_2) * src.GetShape(GlobalTensorDim::DIM_3) ==
75	                 dst.GetValidRow() &&
76	             src.GetShape(GlobalTensorDim::DIM_4) == dst.GetValidCol() && TileData::isRowMajor) ||
77	            (src.GetShape(GlobalTensorDim::DIM_0) * src.GetShape(GlobalTensorDim::DIM_1) *
78	                     src.GetShape(GlobalTensorDim::DIM_2) * src.GetShape(GlobalTensorDim::DIM_4) ==
79	                 dst.GetValidCol() &&
80	             src.GetShape(GlobalTensorDim::DIM_3) == dst.GetValidRow() && !TileData::isRowMajor));
81	    }
82	}
83	
84	template <typename TileData, typename GlobalData>
85	PTO_INTERNAL void CheckConvTileData(TileData& dst, GlobalData& src)
86	{
87	    static_assert(
88	        std::is_same_v<typename TileData::DType, int8_t> || std::is_same_v<typename TileData::DType, uint8_t> ||
89	            std::is_same_v<typename TileData::DType, int16_t> || std::is_same_v<typename TileData::DType, uint16_t> ||
90	            std::is_same_v<typename TileData::DType, int32_t> || std::is_same_v<typename TileData::DType, uint32_t> ||
91	            std::is_same_v<typename TileData::DType, half> || std::is_same_v<typename TileData::DType, bfloat16_t> ||
92	            std::is_same_v<typename TileData::DType, float>,
93	        "Fix: Data type must be int8_t/uint8_t/int16_t/uint16_t/int32_t/uint32_t/half/bfloat16_t/float!");
94	    static_assert(TileData::Loc == pto::TileType::Mat, "Fix: Dst TileType must be Mat!");
95	    static_assert(
96	        sizeof(typename TileData::DType) == sizeof(typename GlobalData::DType),
97	        "Fix: Source dtype must be same with dst dtype!");
98	
99	    constexpr bool isSameLayout =
100	        (GlobalData::layout == pto::Layout::NC1HWC0 && TileData::layout == pto::Layout::NC1HWC0) ||
101	        (GlobalData::layout == pto::Layout::FRACTAL_Z && TileData::layout == pto::Layout::FRACTAL_Z) ||
102	        (GlobalData::layout == pto::Layout::NDC1HWC0 && TileData::layout == pto::Layout::NDC1HWC0);
103	    static_assert(
104	        isSameLayout == true, "Fix: Src and Dst layout must be the same in case of NC1HWC0, NDC1HWC0 or FRACTAL_Z!");
105	
106	    constexpr uint32_t c0ElemCount = C0_SIZE_BYTE / sizeof(typename TileData::DType);
107	
108	    if constexpr (GlobalData::layout == pto::Layout::FRACTAL_Z) {
109	        if constexpr (TileData::totalDimCount == 4) { // ConvTile layout is [C1HW,N/16,16,C0]
110	            static_assert(
111	                TileData::staticShape[2] == FRACTAL_NZ_ROW && TileData::staticShape[3] == c0ElemCount,
112	                "Fix: The TileData last 2 dim must be static and satisfy [16, 32 / sizeof(DataType)]");
113	            static_assert(
114	                GlobalData::staticShape[3] == FRACTAL_NZ_ROW && GlobalData::staticShape[4] == c0ElemCount,
115	                "Fix: The GlobalTensor last 2 dim must be static and satisfy [16, 32 / sizeof(DataType)]");
116	        } else { //  [C1,H,W,N,C0]
117	            assert(
118	                src.GetShape(GlobalTensorDim::DIM_1) == dst.GetShape(GlobalTensorDim::DIM_1) &&
119	                src.GetShape(GlobalTensorDim::DIM_2) == dst.GetShape(GlobalTensorDim::DIM_2) &&
120	                "Fix: layout is Fractal_Z, [srcH,srcW] && [dstH,dstW] should be same!");
121	            assert(dst.GetShape(GlobalTensorDim::DIM_3) <= UINT16_MAX && "Fix: max support dstN is UINT16_MAX!");
122	        }
123	    }
124	}
125	
126	template <typename TileData, typename GlobalData>
127	PTO_INTERNAL void TLOAD_TILE_IMPL(TileData& dst, GlobalData& src)
128	{
129	    CheckTileData<TileData, GlobalData>(dst, src);
130	
131	    const size_t validRow = dst.GetValidRow();
132	    const size_t validCol = dst.GetValidCol();
133	
134	    // Filling padding
135	    std::fill(dst.data(), dst.data() + TileData::GetSizeInUnits(), getPadValue<TileData>());
136	
137	    const std::vector<int64_t> shapes = {
138	        src.GetShape(GlobalTensorDim::DIM_0), src.GetShape(GlobalTensorDim::DIM_1),
139	        src.GetShape(GlobalTensorDim::DIM_2), src.GetShape(GlobalTensorDim::DIM_3),
140	        src.GetShape(GlobalTensorDim::DIM_4)};
141	    const std::vector<int64_t> strides = {
142	        src.GetStride(GlobalTensorDim::DIM_0), src.GetStride(GlobalTensorDim::DIM_1),
143	        src.GetStride(GlobalTensorDim::DIM_2), src.GetStride(GlobalTensorDim::DIM_3),
144	        src.GetStride(GlobalTensorDim::DIM_4)};
145	
146	    for (size_t row = 0; row < validRow; ++row) {
147	        for (size_t col = 0; col < validCol; ++col) {
148	            const size_t dstOffset = MapTileIndicesToGlobalOffset<GlobalData>(row, col, shapes, strides);
149	            dst.SetElement(row, col, GetProperDataPart(src.data(), dstOffset));
150	        }
151	    }
152	}
153	
154	template <typename ConTile, typename GlobalData>
155	__tf__ PTO_INLINE void TLOAD_CONVTILE_IMPL(ConTile& dst, GlobalData& src)
156	{
157	    CheckConvTileData<ConTile, GlobalData>(dst, src);
158	
159	    using T = typename ConTile::DType;
160	    const size_t validRow = CalculateValidRowFromTile(dst);
161	    const size_t validCol = CalculateValidColFromTile(dst);
162	
163	    const std::vector<int64_t> tile_shapes = {
164	        dst.GetShape(GlobalTensorDim::DIM_0), dst.GetShape(GlobalTensorDim::DIM_1),
165	        dst.GetShape(GlobalTensorDim::DIM_2), dst.GetShape(GlobalTensorDim::DIM_3),
166	        dst.GetShape(GlobalTensorDim::DIM_4)};
167	
168	    const std::vector<int64_t> shapes = {
169	        src.GetShape(GlobalTensorDim::DIM_0), src.GetShape(GlobalTensorDim::DIM_1),
170	        src.GetShape(GlobalTensorDim::DIM_2), src.GetShape(GlobalTensorDim::DIM_3),
171	        src.GetShape(GlobalTensorDim::DIM_4)};
172	    const std::vector<int64_t> strides = {
173	        src.GetStride(GlobalTensorDim::DIM_0), src.GetStride(GlobalTensorDim::DIM_1),
174	        src.GetStride(GlobalTensorDim::DIM_2), src.GetStride(GlobalTensorDim::DIM_3),
175	        src.GetStride(GlobalTensorDim::DIM_4)};
176	
177	    for (size_t row = 0; row < validRow; ++row) {
178	        for (size_t col = 0; col < validCol; ++col) {
179	            const size_t srcOffset = MapTileIndicesToGlobalOffset<GlobalData>(row, col, shapes, strides);
180	            dst.data()[GetConvTileElementOffset<ConTile>(row, col, tile_shapes)] = src.data()[srcOffset];
181	        }
182	    }
183	}
184	
185	template <typename TileData, typename GlobalData>
186	PTO_INTERNAL void TLOAD_IMPL(TileData& dst, GlobalData& src)
187	{
188	    if constexpr (is_conv_tile_v<TileData>) {
189	        TLOAD_CONVTILE_IMPL(dst, src);
190	    } else {
191	        TLOAD_TILE_IMPL(dst, src);
192	    }
193	}
194	
195	} // namespace pto
196	#endif
