100	PTO_INTERNAL void TLoadGm2L1Nd2nd(
101	    __cbuf__ typename TileData::DType* dstAddr, typename GlobalData::DType* srcAddr, int gShape0, int gShape1,
102	    int gShape2, int gShape3, int gShape4, int gStride0, int gStride1, int gStride2, int gStride3, int gStride4,
103	    int validRow, int validCol)
104	{
105	    PTO_ASSERT(
106	        gShape4 * sizeof(typename TileData::DType) % BLOCK_BYTE_SIZE == 0,
107	        "The 5th dim of ND shape must be 32 bytes aligned!");
108	    PTO_ASSERT(validCol == gShape4, "The validCol of TileData must be equal to the 5th dim(Shape4) of ND shape!");
109	    PTO_ASSERT(
110	        validRow == gShape0 * gShape1 * gShape2 * gShape3,
111	        "The validRow of TileData must be equal to (Shape0 * Shape1 * Shape2 * Shape3) of ND shape!");
112	    PTO_ASSERT(gShape3 < 4096, "The gshape3 (which equals nBurst) must be less than 4096 for A2/A3");
113	    uint16_t nBurst = gShape3;
114	    uint16_t lenBurst = (validCol * sizeof(typename TileData::DType)) >> SHIFT_BLOCK_BYTE;
115	    uint16_t gmGap = ((gStride3 - gShape4) * sizeof(typename TileData::DType)) >> SHIFT_BLOCK_BYTE;
116	    uint16_t l1Gap = ((TileData::Cols - validCol) * sizeof(typename TileData::DType)) >> SHIFT_BLOCK_BYTE;
117	
118	    int64_t dstStride2 = gShape3 * TileData::Cols;
119	    int64_t dstStride1 = gShape2 * dstStride2;
120	    int64_t dstStride0 = gShape1 * dstStride1;
121	    typename GlobalData::DType* srcAddrP = srcAddr;
122	    __cbuf__ typename TileData::DType* dstAddrP = dstAddr;
123	    for (uint32_t i = 0; i < gShape0; i++) {
124	        int64_t srcAddr0 = i * gStride0;
125	        int64_t dstAddr0 = i * dstStride0;
126	        for (uint32_t j = 0; j < gShape1; j++) {
127	            int64_t dstAddr1 = j * dstStride1;
128	            int64_t srcAddr1 = j * gStride1;
129	            for (uint32_t k = 0; k < gShape2; k++) {
130	                srcAddrP = srcAddr + srcAddr0 + srcAddr1 + k * gStride2;
131	                dstAddrP = dstAddr + dstAddr0 + dstAddr1 + k * dstStride2;
132	                TLoadInstrGm2L1<TileData, GlobalData>(dstAddrP, srcAddrP, nBurst, lenBurst, gmGap, l1Gap);
133	            }
134	        }
135	    }
