244	template <typename TileData, typename GlobalData>
245	__tf__ PTO_INTERNAL void TLoadFractalZ(
246	    typename TileData::TileDType __out__ dst, typename GlobalData::DType __in__* src, int srcShape0, int srcShape1,
247	    int srcShape2, int srcShape3, int srcShape4, int gStride0, int gStride1, int gStride2, int gStride3, int gStride4,
248	    int dstShape0, int dstShape1, int dstShape2, int dstShape3)
249	{
250	    __cbuf__ typename TileData::DType* dstAddr = (__cbuf__ typename TileData::DType*)__cce_get_tile_ptr(dst);
251	    typename GlobalData::DType* srcAddr = src;
252	
253	    constexpr uint32_t c0ElemCount = C0_SIZE_BYTE / sizeof(typename TileData::DType);
254	    typename GlobalData::DType* srcAddrP = srcAddr;
255	    __cbuf__ typename TileData::DType* dstAddrP = dstAddr;
256	
257	    if constexpr (TileData::totalDimCount == 4) {
258	        static_assert(
259	            TileData::staticShape[2] == FRACTAL_NZ_ROW && TileData::staticShape[3] == c0ElemCount,
260	            "Fix: The TileData last 2 dim must be static and satisfy [16, 32 / sizeof(DataType)]");
261	        static_assert(
262	            GlobalData::staticShape[3] == FRACTAL_NZ_ROW && GlobalData::staticShape[4] == c0ElemCount,
263	            "Fix: The GlobalTensor last 2 dim must be static and satisfy [16, 32 / sizeof(DataType)]");
264	
265	        uint16_t nBurst = dstShape0;
266	        uint16_t lenBurst = dstShape1 * dstShape2;
267	        uint16_t gmGap =
268	            ((gStride1 - srcShape2 * srcShape3 * c0ElemCount) * sizeof(typename TileData::DType)) >> SHIFT_BLOCK_BYTE;
269	        TLoadInstrGm2L1<TileData, GlobalData>(dstAddrP, srcAddrP, nBurst, lenBurst, gmGap, 0);
270	
271	    } else {
272	        PTO_ASSERT(
273	            srcShape1 == dstShape1 && srcShape2 == dstShape2,
274	            "Fix: layout is Fractal_Z, [srcH,srcW] && [dstH,dstW] should be same!");
275	        PTO_ASSERT(dstShape3 <= UINT16_MAX, "Fix: max support dstN is UINT16_MAX!");
276	
277	        uint16_t lenBurst = dstShape3;
278	        uint16_t gmGap = ((gStride2 - srcShape3 * c0ElemCount) * sizeof(typename TileData::DType)) >> SHIFT_BLOCK_BYTE;
279	        constexpr uint32_t maxSupportBurst = 4095;
280	
281	        if (dstShape0 * dstShape1 * dstShape2 <= maxSupportBurst) {
282	            uint16_t nBurst = dstShape0 * dstShape1 * dstShape2;
283	            TLoadInstrGm2L1<TileData, GlobalData>(dstAddrP, srcAddrP, nBurst, lenBurst, gmGap, 0);
284	        } else {
285	            uint16_t nBurst = dstShape1 * dstShape2;
286	            for (uint32_t i = 0; i < dstShape0; i++) {
287	                srcAddrP = srcAddr + i * gStride0;
288	                dstAddrP = dstAddr + i * dstShape1 * dstShape2 * dstShape3 * c0ElemCount;
289	                TLoadInstrGm2L1<TileData, GlobalData>(dstAddrP, srcAddrP, nBurst, lenBurst, gmGap, 0);
290	            }
291	        }
292	    }
293	}
