61	        dst.GetStride(GlobalTensorDim::DIM_4)};
62	
63	    uint64_t scalar = 0;
64	    for (size_t row = 0; row < validRow; ++row) {
65	        for (size_t col = 0; col < validCol; ++col) {
66	            if constexpr (quantMode != QuantMode_t::NoQuant) {
67	                scalar = scalars[TileData::isRowMajor ? col : row];
68	            }
69	            ST val = src.GetElement(row, col);
70	            DT dstVal = ConvertStoreValue<DT, ST, quantMode, applyRelu>(val, scalar);
71	            const size_t dstOffset = MapTileIndicesToGlobalOffset<GlobalData>(row, col, shapes, strides);
