67	template <typename GlobalData, typename TileData>
68	PTO_INTERNAL void TStoreUb2gmNz2nz(
69	    typename GlobalData::DType* dstAddr, __ubuf__ typename TileData::DType* srcAddr, int gShape0, int gShape1,
70	    int gShape2, int gShape3, int gShape4, int gStride0, int gStride1, int gStride2, int gStride3, int gStride4,
71	    int validRow, int validCol)
72	{
73	    static_assert(
74	        GlobalData::staticShape[3] == FRACTAL_NZ_ROW &&
75	            GlobalData::staticShape[4] == BLOCK_BYTE_SIZE / sizeof(typename TileData::DType),
76	        "When TileData is NZ format, the last 2 dim must be static and satisfy [16, 32 / sizeof(DataType)]");
77	    PTO_ASSERT(validRow == gShape2 * gShape3, "The validRow of TileData must be equal to Shape2 * Shape3 of NZ shape!");
78	    PTO_ASSERT(
79	        validCol == gShape0 * gShape1 * gShape4,
80	        "The validCol of TileData must be equal to Shape0 * Shape1 * Shape4 of NZ shape!");
81	    PTO_ASSERT(gShape1 < 4096, "The gshape1 (which equals nBurst) must be less than 4096");
82	    uint16_t nBurst = gShape1;
83	    uint32_t lenBurst = validRow * C0_SIZE_BYTE;
84	    uint32_t gmGap = (gStride1 - gShape2 * gShape3 * gShape4) * sizeof(typename TileData::DType);
85	    uint32_t ubGap = TileData::Rows - validRow;
86	
87	    typename GlobalData::DType* dstGlobalAddr = dstAddr;
88	    __ubuf__ typename TileData::DType* srcTileAddr = srcAddr;
89	
90	    int64_t tileStride = TileData::Rows * gShape1 * gShape4;
91	    for (uint32_t i = 0; i < gShape0; i++) {
92	        dstGlobalAddr = dstAddr + i * gStride0;
93	        srcTileAddr = srcAddr + i * tileStride;
94	        TStoreUb2gmInstr<GlobalData, TileData>(dstGlobalAddr, srcTileAddr, nBurst, lenBurst, gmGap, ubGap);
95	    }
96	}
