28	// case shape is static, but testing would do dynamic or static test
29	template <int shape0, int shape1, int shape2, int shape3, int shape4>
30	AICORE __inline__ auto getOptDynShape(int gShape0, int gShape1, int gShape2, int gShape3, int gShape4)
31	{
32	    if constexpr (shape0 == 1) {
33	        using DynShapeDim5 = Shape<1, -1, -1, -1, -1>;
34	        DynShapeDim5 dynShape(gShape1, gShape2, gShape3, gShape4);
35	        return dynShape;
36	    } else if constexpr (shape0 == 1 && shape1 == 1) {
37	        using DynShapeDim5 = Shape<1, 1, -1, -1, -1>;
38	        DynShapeDim5 dynShape(gShape2, gShape3, gShape4);
39	        return dynShape;
40	    } else if constexpr (shape0 == 1 && shape1 == 1 && shape2 == 1) {
41	        using DynShapeDim5 = Shape<1, 1, 1, -1, -1>;
42	        DynShapeDim5 dynShape(gShape3, gShape4);
43	        return dynShape;
44	    } else if constexpr (shape0 == 1 && shape1 == 1 && shape2 == 1 && shape3 == 1) {
45	        using DynShapeDim5 = Shape<1, 1, 1, 1, -1>;
46	        DynShapeDim5 dynShape(gShape4);
47	        return dynShape;
48	    } else {
49	        using DynShapeDim5 = Shape<-1, -1, -1, -1, -1>;
50	        DynShapeDim5 dynShape(gShape0, gShape1, gShape2, gShape3, gShape4);
51	        return dynShape;
52	    }
53	}
