55	// case shape is static, but testing would do dynamic or static test
56	template <
57	    typename T, int shape0, int shape1, int shape2, int shape3, int shape4, int tRows, int tCols, BLayout major,
58	    int dyn>
59	AICORE __inline__ auto getGlobalTensor(__gm__ T* addr, int gShape0, int gShape1, int gShape2, int gShape3, int gShape4)
60	{
61	    if constexpr (dyn) {
62	        int stride0 = gShape1 * gShape2 * shape3 * shape4;
63	        int stride1 = gShape2 * shape3 * shape4;
64	        int stride2 = shape3 * shape4;
65	
66	        using DynStrideDim5 = pto::Stride<-1, -1, -1, -1, -1>;
67	        auto dynShape =
68	            getOptDynShape<shape0, shape1, shape2, shape3, shape4>(gShape0, gShape1, gShape2, gShape3, gShape4);
69	        using GlobalData = GlobalTensor<T, decltype(dynShape), DynStrideDim5, pto::Layout::DN>;
70	
71	        if constexpr (major == BLayout::RowMajor) {
72	            GlobalData srcGlobal(addr, dynShape, DynStrideDim5(stride0, stride1, stride2, shape4, 1));
73	            return srcGlobal;
74	        } else {
75	            GlobalData srcGlobal(addr, dynShape, DynStrideDim5(stride0, stride1, stride2, 1, shape3));
76	            return srcGlobal;
77	        }
78	    } else // static
79	    {
80	        constexpr int stride0 = shape1 * shape2 * shape3 * shape4;
81	        constexpr int stride1 = shape2 * shape3 * shape4;
82	        constexpr int stride2 = shape3 * shape4;
83	        using StaticShapeDim5 = Shape<shape0, shape1, shape2, tRows, tCols>;
84	
85	        if constexpr (major == BLayout::RowMajor) {
86	            using StaticStrideDim5 = pto::Stride<stride0, stride1, stride2, shape4, 1>;
87	            using GlobalData = GlobalTensor<T, StaticShapeDim5, StaticStrideDim5>;
88	            GlobalData srcGlobal(addr);
89	            return srcGlobal;
90	        } else {
91	            using StaticStrideDim5 = pto::Stride<stride0, stride1, stride2, 1, shape3>;
92	            using GlobalData = GlobalTensor<T, StaticShapeDim5, StaticStrideDim5>;
93	            GlobalData srcGlobal(addr);
94	            return srcGlobal;
95	        }
96	    }
97	}
