99	template <
100	    typename T, int shape0, int shape1, int shape2, int shape3, int shape4, int tRows, int tCols, BLayout major,
101	    int dyn>
102	AICORE __inline__ auto getGlobalTensorNZ(
103	    __gm__ T* addr, int gShape0, int gShape1, int gShape2, int gShape3, int gShape4)
104	{
105	    constexpr int blockSize = 32 / sizeof(T);
106	    constexpr int innerCols = blockSize;
107	    constexpr int innerRows = 16;
108	
109	    if constexpr (dyn) {
110	        int stride0 = gShape1 * gShape2 * innerRows * innerCols;
111	        int stride1 = gShape2 * innerRows * innerCols;
112	        int stride2 = innerRows * innerCols;
113	
114	        using DynShapeDim5 = Shape<-1, -1, -1, -1, -1>;
115	        DynShapeDim5 dynShape(gShape0, gShape1, gShape2, innerRows, innerCols);
116	        using DynStrideDim5 = pto::Stride<-1, -1, -1, -1, -1>;
117	        using GlobalData = GlobalTensor<T, DynShapeDim5, DynStrideDim5, Layout::NZ>;
118	
119	        GlobalData srcGlobal(addr, dynShape, DynStrideDim5(stride0, stride1, stride2, innerCols, 1));
120	        return srcGlobal;
121	    } else // static
122	    {
123	        constexpr int stride0 = shape1 * shape2 * innerRows * innerCols;
124	        constexpr int stride1 = shape2 * innerRows * innerCols;
125	        constexpr int stride2 = innerRows * innerCols;
126	
127	        using StaticShapeDim5 = Shape<shape0, shape1, shape2, innerRows, innerCols>;
128	        using StaticStrideDim5 = pto::Stride<stride0, stride1, stride2, innerCols, 1>;
129	        using GlobalData = GlobalTensor<T, StaticShapeDim5, StaticStrideDim5, Layout::NZ>;
130	
131	        GlobalData srcGlobal(addr);
132	        return srcGlobal;
133	    }
134	}
