139	template <
140	    typename T, int shape0, int shape1, int shape2, int shape3, int shape4, int kTRows_, int kTCols_, int dyn_,
141	    PadValue PadVal_ = PadValue::Null>
142	AICORE void runTLOADND(
143	    __gm__ T* out, __gm__ T* src, int gShape0, int gShape1, int gShape2, int gRows, int gCols, __gm__ uint64_t* gLog)
144	{
145	    using TileData =
146	        Tile<TileType::Vec, T, kTRows_, kTCols_, BLayout::RowMajor, -1, -1, SLayout::NoneBox, 512, PadVal_>;
147	    TileData vecTile(kTRows_, gCols);
148	
149	    constexpr int kGTRows = kTRows_ / shape0 / shape1 / shape2; // Dst Tile Rows, merged all shape0*shape1*shape2 row
150	    constexpr int shape4_aligned = align_to_32B(shape4, T);
151	    auto srcGlobal =
152	        getGlobalTensor<T, shape0, shape1, shape2, kGTRows, shape4, kGTRows, shape4, BLayout::RowMajor, dyn_>(
153	            src, gShape0, gShape1, gShape2, kGTRows, shape4);
154	
155	    TASSIGN(vecTile, 0);
156	
157	    TLOAD(vecTile, srcGlobal);
158	    for (size_t i = 0; i < TileData::Rows * TileData::Cols; i++) {
159	        out[i] = vecTile.data()[i];
160	    }
161	}
