351	int get_input_golden_case(uint8_t* input, uint8_t* golden)
352	{
353	    constexpr int shape4_aligned = align_to_32B(Shape4, T);
354	    static_assert((Shape3 % (Shape0 * Shape1 * Shape2)) == 0);
355	    constexpr int sh3 = Shape3 / (Shape0 * Shape1 * Shape2);
356	    int in_byteSize = Shape0 * Shape1 * Shape2 * sh3 * Shape4 * sizeof(T);
357	    int out_byteSize = Shape0 * Shape1 * Shape2 * sh3 * shape4_aligned * sizeof(T);
358	
359	    T in_arr[Shape0][Shape1][Shape2][sh3][Shape4] = {};
360	    T gold_arr[Shape0][Shape1][Shape2][sh3][shape4_aligned] = {};
361	
362	    for (int x0 = 0; x0 < Shape0; x0++)
363	        for (int x1 = 0; x1 < Shape1; x1++)
364	            for (int x2 = 0; x2 < Shape2; x2++)
365	                for (int i = 0; i < sh3; i++) {
366	                    for (int j = 0; j < shape4_aligned; j++) {
367	                        if (j < Shape4) {
368	                            in_arr[x0][x1][x2][i][j] = x0 * Shape1 * Shape2 * sh3 * Shape4 +
369	                                                       x1 * Shape2 * sh3 * Shape4 + x2 * sh3 * Shape4 + i * Shape4 + j;
370	                            gold_arr[x0][x1][x2][i][j] = in_arr[x0][x1][x2][i][j];
371	                        } else {
372	                            if (std::numeric_limits<T>::has_infinity) {
373	                                if (PadVal_ == PadValue::Max)
374	                                    gold_arr[x0][x1][x2][i][j] = std::numeric_limits<T>::infinity();
375	                                else if (PadVal_ == PadValue::Min)
376	                                    gold_arr[x0][x1][x2][i][j] = -std::numeric_limits<T>::infinity();
377	                                else
378	                                    gold_arr[x0][x1][x2][i][j] = 0;
379	                            } else {
380	                                if (PadVal_ == PadValue::Max)
381	                                    gold_arr[x0][x1][x2][i][j] = std::numeric_limits<T>::max();
382	                                else if (PadVal_ == PadValue::Min)
383	                                    gold_arr[x0][x1][x2][i][j] = std::numeric_limits<T>::min();
384	                                else
385	                                    gold_arr[x0][x1][x2][i][j] = 0;
386	                            }
387	                        }
388	                    } // j
389	                } // i
390	
391	    std::copy((uint8_t*)in_arr, ((uint8_t*)(in_arr)) + in_byteSize, input);
392	    std::copy((uint8_t*)gold_arr, ((uint8_t*)(gold_arr)) + out_byteSize, golden);
393	    return sizeof(gold_arr);
394	}
