#include <pto/pto-inst.hpp>
#include <pto/common/constants.hpp>
#include <limits>
#include <algorithm>

using namespace std;
using namespace pto;

#define LOGSIZE 128
#define PRINTLOG 4
#define DEBUGLOG
#ifdef DEBUGLOG
#define LOG(x) (*(gLog++) = x)
#else
#define LOG(x)
#endif

// case shape is static, but testing would do dynamic or static test
template <int shape0, int shape1, int shape2, int shape3, int shape4>
AICORE __inline__ auto getOptDynShape(int gShape0, int gShape1, int gShape2, int gShape3, int gShape4)
{
    if constexpr (shape0 == 1) {
        using DynShapeDim5 = Shape<1, -1, -1, -1, -1>;
        DynShapeDim5 dynShape(gShape1, gShape2, gShape3, gShape4);
        return dynShape;
    } else if constexpr (shape0 == 1 && shape1 == 1) {
        using DynShapeDim5 = Shape<1, 1, -1, -1, -1>;
        DynShapeDim5 dynShape(gShape2, gShape3, gShape4);
        return dynShape;
    } else if constexpr (shape0 == 1 && shape1 == 1 && shape2 == 1) {
        using DynShapeDim5 = Shape<1, 1, 1, -1, -1>;
        DynShapeDim5 dynShape(gShape3, gShape4);
        return dynShape;
    } else if constexpr (shape0 == 1 && shape1 == 1 && shape2 == 1 && shape3 == 1) {
        using DynShapeDim5 = Shape<1, 1, 1, 1, -1>;
        DynShapeDim5 dynShape(gShape4);
        return dynShape;
    } else {
        using DynShapeDim5 = Shape<-1, -1, -1, -1, -1>;
        DynShapeDim5 dynShape(gShape0, gShape1, gShape2, gShape3, gShape4);
        return dynShape;
    }
}

// case shape is static, but testing would do dynamic or static test
template <
    typename T, int shape0, int shape1, int shape2, int shape3, int shape4, int tRows, int tCols, BLayout major,
    int dyn>
AICORE __inline__ auto getGlobalTensor(__gm__ T* addr, int gShape0, int gShape1, int gShape2, int gShape3, int gShape4)
{
    if constexpr (dyn) {
        int stride0 = gShape1 * gShape2 * shape3 * shape4;
        int stride1 = gShape2 * shape3 * shape4;
        int stride2 = shape3 * shape4;

        using DynStrideDim5 = pto::Stride<-1, -1, -1, -1, -1>;
        auto dynShape =
            getOptDynShape<shape0, shape1, shape2, shape3, shape4>(gShape0, gShape1, gShape2, gShape3, gShape4);
        using GlobalData = GlobalTensor<T, decltype(dynShape), DynStrideDim5, pto::Layout::DN>;

        if constexpr (major == BLayout::RowMajor) {
            GlobalData srcGlobal(addr, dynShape, DynStrideDim5(stride0, stride1, stride2, shape4, 1));
            return srcGlobal;
        } else {
            GlobalData srcGlobal(addr, dynShape, DynStrideDim5(stride0, stride1, stride2, 1, shape3));
            return srcGlobal;
        }
    } else // static
    {
        constexpr int stride0 = shape1 * shape2 * shape3 * shape4;
        constexpr int stride1 = shape2 * shape3 * shape4;
        constexpr int stride2 = shape3 * shape4;
        using StaticShapeDim5 = Shape<shape0, shape1, shape2, tRows, tCols>;

        if constexpr (major == BLayout::RowMajor) {
            using StaticStrideDim5 = pto::Stride<stride0, stride1, stride2, shape4, 1>;
            using GlobalData = GlobalTensor<T, StaticShapeDim5, StaticStrideDim5>;
            GlobalData srcGlobal(addr);
            return srcGlobal;
        } else {
            using StaticStrideDim5 = pto::Stride<stride0, stride1, stride2, 1, shape3>;
            using GlobalData = GlobalTensor<T, StaticShapeDim5, StaticStrideDim5>;
            GlobalData srcGlobal(addr);
            return srcGlobal;
        }
    }
}

template <
    typename T, int shape0, int shape1, int shape2, int shape3, int shape4, int tRows, int tCols, BLayout major,
    int dyn>
AICORE __inline__ auto getGlobalTensorNZ(
    __gm__ T* addr, int gShape0, int gShape1, int gShape2, int gShape3, int gShape4)
{
    constexpr int blockSize = 32 / sizeof(T);
    constexpr int innerCols = blockSize;
    constexpr int innerRows = 16;

    if constexpr (dyn) {
        int stride0 = gShape1 * gShape2 * innerRows * innerCols;
        int stride1 = gShape2 * innerRows * innerCols;
        int stride2 = innerRows * innerCols;

        using DynShapeDim5 = Shape<-1, -1, -1, -1, -1>;
        DynShapeDim5 dynShape(gShape0, gShape1, gShape2, innerRows, innerCols);
        using DynStrideDim5 = pto::Stride<-1, -1, -1, -1, -1>;
        using GlobalData = GlobalTensor<T, DynShapeDim5, DynStrideDim5, Layout::NZ>;

        GlobalData srcGlobal(addr, dynShape, DynStrideDim5(stride0, stride1, stride2, innerCols, 1));
        return srcGlobal;
    } else // static
    {
        constexpr int stride0 = shape1 * shape2 * innerRows * innerCols;
        constexpr int stride1 = shape2 * innerRows * innerCols;
        constexpr int stride2 = innerRows * innerCols;

        using StaticShapeDim5 = Shape<shape0, shape1, shape2, innerRows, innerCols>;
        using StaticStrideDim5 = pto::Stride<stride0, stride1, stride2, innerCols, 1>;
        using GlobalData = GlobalTensor<T, StaticShapeDim5, StaticStrideDim5, Layout::NZ>;

        GlobalData srcGlobal(addr);
        return srcGlobal;
    }
}

#define type_32_aligned(T) (32 / sizeof(T))
#define align_to_32B(x, T) ((((x) + type_32_aligned(T) - 1) / type_32_aligned(T)) * (type_32_aligned(T)))

template <
    typename T, int shape0, int shape1, int shape2, int shape3, int shape4, int kTRows_, int kTCols_, int dyn_,
    PadValue PadVal_ = PadValue::Null>
AICORE void runTLOADND(
    __gm__ T* out, __gm__ T* src, int gShape0, int gShape1, int gShape2, int gRows, int gCols, __gm__ uint64_t* gLog)
{
    using TileData =
        Tile<TileType::Vec, T, kTRows_, kTCols_, BLayout::RowMajor, -1, -1, SLayout::NoneBox, 512, PadVal_>;
    TileData vecTile(kTRows_, gCols);

    constexpr int kGTRows = kTRows_ / shape0 / shape1 / shape2; // Dst Tile Rows, merged all shape0*shape1*shape2 row
    constexpr int shape4_aligned = align_to_32B(shape4, T);
    auto srcGlobal =
        getGlobalTensor<T, shape0, shape1, shape2, kGTRows, shape4, kGTRows, shape4, BLayout::RowMajor, dyn_>(
            src, gShape0, gShape1, gShape2, kGTRows, shape4);

    TASSIGN(vecTile, 0);

    TLOAD(vecTile, srcGlobal);
    for (size_t i = 0; i < TileData::Rows * TileData::Cols; i++) {
        out[i] = vecTile.data()[i];
    }
}

template <
    typename T, int shape0, int shape1, int shape2, int shape3, int shape4, int kTRows_, int kTCols_, int dyn_,
    PadValue PadVal_ = PadValue::Null>
AICORE void runTLOADDN(
    __gm__ T* out, __gm__ T* src, int gShape0, int gShape1, int gShape2, int gRows, int gCols, __gm__ uint64_t* gLog)
{
    using TileData =
        Tile<TileType::Vec, T, kTRows_, kTCols_, BLayout::ColMajor, -1, -1, SLayout::NoneBox, 512, PadVal_>;
    TileData vecTile(gRows, gCols);

    constexpr int kGTCols = kTCols_ / shape0 / shape1 / shape2; // Dst Tile Rows, merged all shape0*shape1*shape2 row
    auto srcGlobal =
        getGlobalTensor<T, shape0, shape1, shape2, shape3, kGTCols, shape3, kGTCols, BLayout::RowMajor, dyn_>(
            src, gShape0, gShape1, gShape2, shape3, kGTCols);

    TASSIGN(vecTile, 0);

    TLOAD(vecTile, srcGlobal);
    for (size_t i = 0; i < TileData::Rows * TileData::Cols; i++) {
        out[i] = vecTile.data()[i];
    }
}

template <
    typename T, int shape0, int shape1, int shape2, int shape3, int shape4, int kTRows_, int kTCols_, int dyn_,
    PadValue PadVal_ = PadValue::Null>
AICORE void runTLOADNZ(
    __gm__ T* out, __gm__ T* src, int gShape0, int gShape1, int gShape2, int gRows, int gCols, __gm__ uint64_t* gLog)
{
    constexpr int Rows = shape2 * shape3;
    constexpr int Cols = shape0 * shape1 * shape4;
    constexpr int blockSize = 32 / sizeof(T);
    constexpr int alignedCols = (Cols + blockSize - 1) / blockSize * blockSize;

    using TileData =
        Tile<TileType::Vec, T, Rows, alignedCols, BLayout::ColMajor, -1, -1, SLayout::RowMajor, 512, PadVal_>;
    TileData vecTile(Rows, Cols);
    auto srcGlobal =
        getGlobalTensorNZ<T, shape0, shape1, shape2, shape3, shape4, Rows, alignedCols, BLayout::RowMajor, dyn_>(
            src, gShape0, gShape1, gShape2, shape3, shape4);

    TASSIGN(vecTile, 0);

    TLOAD(vecTile, srcGlobal);
    for (size_t i = 0; i < TileData::Rows * TileData::Cols; i++) {
        out[i] = vecTile.data()[i];
    }
}

extern "C" __global__ AICORE void launchTLOAD_1(
    __gm__ uint8_t* out, __gm__ uint8_t* src, int gShape0, int gShape1, int gShape2, int gRows, int gCols,
    __gm__ uint64_t* gLog)
{
    runTLOADND<float, 1, 1, 1, 128, 128, 128, 128, 1, PadValue::Null>(
        (__gm__ float*)out, (__gm__ float*)src, gShape0, gShape1, gShape2, gRows, gCols, gLog);
}

extern "C" __global__ AICORE void launchTLOAD_2(
    __gm__ uint8_t* out, __gm__ uint8_t* src, int gShape0, int gShape1, int gShape2, int gRows, int gCols,
    __gm__ uint64_t* gLog)
{
    runTLOADND<float, 2, 2, 2, 256, 64, 256, 64, 1, PadValue::Null>(
        (__gm__ float*)out, (__gm__ float*)src, gShape0, gShape1, gShape2, gRows, gCols, gLog);
