253	__tf__ PTO_INTERNAL void TLoadGm2L1Nd2nz(
254	    typename TileData::TileDType __out__ dst, typename GlobalData::DType __in__* src, int gShape0, int gShape1,
255	    int gShape2, int gShape3, int gShape4, int gStride0, int gStride1, int gStride2, int gStride3, int gStride4,
256	    int validRow, int validCol)
257	{
258	    __cbuf__ typename TileData::DType* dstAddr = (__cbuf__ typename TileData::DType*)__cce_get_tile_ptr(dst);
259	    typename GlobalData::DType* srcAddr = src;
260	    static_assert(
261	        GlobalData::staticShape[0] == 1 && GlobalData::staticShape[1] == 1 && GlobalData::staticShape[2] == 1,
262	        "Fix: GlobalTensor only support 2 dim when ND2NZ!");
263	    static_assert(TileData::SFractalSize == 512, "Fix: TileData only support SFractalSize = 512Bytes!");
264	    PTO_ASSERT(gShape3 > 0 && gShape3 <= 16384, "The Shape3 of GlobalTensor must be in range of [1, 16384]!");
